54:   // it calls come from SWR calls that are keyed off what the store holds. Registering a stable
55:   // indirection through a ref breaks that cycle, so the store is read once per hook rather than
56:   // once to get the key and again to register.
57:   const mutateVisitRef = useRef<() => void>(undefined);
58:   const registeredMutateVisit = useCallback(() => mutateVisitRef.current?.(), []);
59:   const {
60:     patientUuid: visitStorePatientUuid,
61:     manuallySetVisitUuid,
62:     setVisitContext,
63:   } = useVisitContextStore(registeredMutateVisit);
64:   // Ignore the visit store data if it is not for this patient
65:   const retrospectiveVisitUuid = patientUuid && visitStorePatientUuid == patientUuid ? manuallySetVisitUuid : null;
66:   const activeVisitUrlSuffix = `?patient=${patientUuid}&v=${representation}&includeInactive=false`;
67:   const retrospectiveVisitUrlSuffix = `/${retrospectiveVisitUuid}?v=${representation}`;
68: 
69:   const {
70:     data: activeData,
71:     error: activeError,
72:     mutate: activeMutate,
73:     isValidating: activeIsValidating,
74:   } = useSWR<{
75:     data: { results: Array<Visit> };
76:   }>(patientUuid ? `${restBaseUrl}/visit${activeVisitUrlSuffix}` : null, openmrsFetch);
