78:   const {
79:     data: retroData,
80:     error: retroError,
81:     mutate: retroMutate,
82:     isValidating: retroIsValidating,
83:   } = useSWR<{
84:     data: Visit;
85:   }>(patientUuid && retrospectiveVisitUuid ? `${restBaseUrl}/visit${retrospectiveVisitUrlSuffix}` : null, openmrsFetch);
86: 
87:   const activeVisit = useMemo(
88:     () => activeData?.data.results.find((visit) => visit.stopDatetime === null) ?? null,
89:     [activeData],
90:   );
91: 
92:   const currentVisit = useMemo(
93:     () => (retrospectiveVisitUuid && retroData ? retroData.data : null),
94:     [retroData, retrospectiveVisitUuid],
95:   );
96:   const previousCurrentVisit = useRef<Visit | null>(null);
